"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type ParallaxPrimitiveProps = ComponentProps<typeof motion.div>;

export function ParallaxPrimitive({ children, ...props }: ParallaxPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {y: 24}}
      animate={{y: -24}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.22, ease: [0.23, 1, 0.32, 1] }}

    >
      {children}
    </motion.div>
  );
}
